package org.concord.biologica.datasupport;import java.util.Hashtable;import java.awt.Image;import java.awt.Component;import java.awt.Toolkit;import java.awt.image.ImageFilter;import java.awt.image.ImageProducer;import java.awt.image.FilteredImageSource;import java.awt.image.ColorModel;public class DataOrganism{static Hashtable cache 		= new Hashtable();Integer	hashKey;ShortImageDescription partsDesc;	public static Integer getHashKey(int size,int partKind,int nPart,int nColor){		int key = size;		key <<= 8;		key += partKind;		key <<= 16;		key += (nPart << 8);		key += nColor;		return new Integer(key);	}	public static Image getOrganismPartImage(ShortImageDescription partsDesc, Object hash,int partNumber, int color, int xoffset[],int yoffset[]){		if(partsDesc == null || hash == null) return null;		Image img = (Image)cache.get(hash);		if(partsDesc.allImages){			int xNumb = partsDesc.xNumb;			if(xNumb > 0) partNumber = color + xNumb * partNumber;		}		if(img == null){			if(partNumber < 0 || partsDesc.images == null || partNumber >= partsDesc.images.length){				return  null;			}			img 	= partsDesc.images[partNumber];			if(!partsDesc.allImages){				if(img != null) img = ImageReader.getImageByColor(img,color);			}			if(img != null) cache.put(hash,img);		}		if(xoffset != null) xoffset[0] = partsDesc.xoffsets[partNumber];		if(yoffset != null) yoffset[0] = partsDesc.yoffsets[partNumber];		return img;	}	public static Image getOrganismPartImage(int []pixels,int worig,ShortImageDescription partsDesc, Object hash,int partNumber, int color, int xoffset[],int yoffset[]){		if(partsDesc == null || hash == null) return null;		Image img = (Image)cache.get(hash);		if(partsDesc.allImages){			int xNumb = partsDesc.xNumb;			if(xNumb > 0) partNumber = color + xNumb * partNumber;		}		if(img == null){			if(partNumber < 0 || partsDesc.images == null || partNumber >= partsDesc.images.length){				return  null;			}			img 	= partsDesc.images[partNumber];			if(!partsDesc.allImages){				if(img != null) img = ImageReader.getImageByColor(img,color);			}			if(img != null) cache.put(hash,img);		}		xoffset[0] = partsDesc.xoffsets[partNumber];		yoffset[0] = partsDesc.yoffsets[partNumber];		TFilter tf = new TFilter(pixels,worig,xoffset[0],yoffset[0]);		ImageProducer ip = img.getSource();		ip = new FilteredImageSource(ip,tf);		Toolkit toolkit = Toolkit.getDefaultToolkit();		toolkit.prepareImage(toolkit.createImage(ip),-1,-1,null);		return img;	}	}class TFilter extends ImageFilter{int []pixels;int xoffset;int yoffset;int origscansize;	public TFilter(int []pixels,int origscansize,int xoffset,int yoffset){		super();		this.pixels = pixels;		this.xoffset = xoffset;		this.yoffset = yoffset;		this.origscansize = origscansize;	}    public synchronized void setPixels(	int x, int y, int w, int h,			  				ColorModel model, byte pix[], int off,			  				int scansize) {		for(int i = 0; i < w; i++){			for(int j = 0; j < h; j++){				int index = i + j*scansize + off;				if(model.getAlpha(pix[index] & 0xFF) < 255){					continue;				}				int indexO = xoffset + x+i + (yoffset+y+j)*origscansize;				pixels[indexO] = model.getRGB(pix[index] & 0xFF);			}		}	}    public synchronized void setPixels(	int x, int y, int w, int h,			  				ColorModel model, int pix[], int off,			  				int scansize) {		for(int i = 0; i < w; i++){			for(int j = 0; j < h; j++){				int index = i + j*scansize + off;				int px = pix[index];				if((px & 0xFF000000) != 0xFF000000){					continue;				}				int indexO = xoffset + x+i + (yoffset+y+j)*origscansize;				pixels[indexO] = px;			}		}    }        }